INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT112-S3-Q10$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Jennifer) Peter is right, and here is another reason.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Mildly drought-stressed plants put some of their resources into making pesticidal toxins. Well-watered plants do not.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Peter's reason for watering lightly is that insects prefer the tender leaves of well-watered plants. Jennifer's fact has nothing to do with leaf texture. It is a second, separate reason for the same advice: stressed plants defend themselves with toxins. Same conclusion, a new road to it.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Supporting Peter's conclusion with an independent reason.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT112-S3-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
